def _normalize_trust_level(raw: str | None) -> str:
    if raw in ("confirmed", "partially_confirmed", "evaluator_surfaced"):
        return raw
    if raw in ("unconfirmed", "invalid_reasoning"):
        return "evaluator_surfaced"
    return "partially_confirmed"

